using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---

var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for the given query and returns a list of result snippets with titles and URLs."),

    AIFunctionFactory.Create(
        ([Description("A concise label for this note")] string title,
         [Description("The note content to save")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note for later reference. Use this to record key findings as you research."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Returns all saved research notes.")
};

// --- Build chat client with automatic tool invocation ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Agent loop ---

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When the user gives you a topic:
            1. Search the web multiple times with varied queries to gather broad information.
            2. Save important findings as notes using the save_note tool.
            3. After you have gathered enough information (at least 3-5 searches), retrieve
               your notes and write a well-structured summary with key findings and source URLs.
            Be thorough but concise. Always cite your sources.
            """),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
    };

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    var options = new ChatOptions { Tools = tools };

    await foreach (var update in client.GetStreamingResponseAsync(messages, options))
    {
        if (update.Text is { } text)
            Console.Write(text);
    }

    Console.WriteLine("\n");
}

// --- Supporting types ---

/// <summary>Performs web searches via DuckDuckGo Lite (no API key required).</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            var response = await Http.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            return ParseResults(html, query);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string ParseResults(string html, string query)
    {
        var results = new List<string>();

        // Extract result snippets from DuckDuckGo Lite HTML.
        var snippetSpans = html.Split("<td class=\"result-snippet\">",
            StringSplitOptions.RemoveEmptyEntries);

        var linkSpans = html.Split("<a rel=\"nofollow\" href=\"",
            StringSplitOptions.RemoveEmptyEntries);

        var urls = new List<string>();
        foreach (var link in linkSpans.Skip(1))
        {
            var end = link.IndexOf('"');
            if (end > 0)
                urls.Add(link[..end]);
        }

        for (int i = 1; i < snippetSpans.Length && results.Count < 5; i++)
        {
            var snippet = StripHtml(snippetSpans[i].Split("</td>")[0]).Trim();
            var urlText = i - 1 < urls.Count ? urls[i - 1] : "";
            if (!string.IsNullOrWhiteSpace(snippet))
                results.Add($"- {snippet}\n  Source: {urlText}");
        }

        return results.Count > 0
            ? $"Search results for \"{query}\":\n{string.Join("\n", results)}"
            : $"No results found for \"{query}\". Try a different query.";
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder();
        bool inTag = false;
        foreach (char c in html)
        {
            if (c == '<') inTag = true;
            else if (c == '>') inTag = false;
            else if (!inTag) sb.Append(c);
        }
        return WebUtility.HtmlDecode(sb.ToString());
    }
}

/// <summary>Simple in-memory notebook for saving and retrieving research notes.</summary>
class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));

    public void Clear() => _notes.Clear();

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i].Title}\n{_notes[i].Content}\n");
        return sb.ToString();
    }
}

